19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	};
29	
30	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
31	
32	const BLOCK_SIZE = 3;
33	const BLOCK_BASE_PREMIUM = 60;
34	
35	const totalBasePremiumOf = (items: Item[]): number => {
36	  if (items.length === BLOCK_SIZE && items.every((i) => i.type === "rune")) {
37	    return BLOCK_BASE_PREMIUM;
38	  }
39	
40	  return items.reduce((total, item) => total + basePremiumOf(item), 0);
41	};
42	
43	const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
44	
45	const quotePremium = (items: Item[]): number => {
46	  const basePremium = totalBasePremiumOf(items);
47	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
48	
49	  return roundedInMHPCOsFavour(
50	    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
51	  );
52	};
53	
54	export const runScenario = (scenario: Scenario): ScenarioResult => ({
55	  results: scenario.steps.map((step) => ({
56	    premium: quotePremium(step.items),
57	  })),
58	});
